"use client"
import { useState } from "react";
import Questions from "./components/Question";

export default function FaQ() {
    const showAnswer = (index)=>{
        setShowSelectedQ(index)
    }
    const [ShowSelectedQ, setShowSelectedQ] = useState(null);
    const data = [
        {
            id: 1,
            question: "Kursus apa saja yang tersedia di Kodein Edu Center?",
            answer: "Kami menyediakan berbagai program, antara lain: Pelajaran Umum (Matematika, IPA, dll sesuai jenjang), Internet of Things (IoT), Web Development, UI&UX Designer, Graphic Designer, Digital Marketing"
        },
        {
            id: 2,
            question: "Apakah kursus ini cocok untuk pemula?",
            answer: "Ya. Semua kursus dirancang bertahap, mulai dari dasar hingga lanjutan, sehingga sangat cocok untuk pemula maupun peserta yang ingin memperdalam skill."
        },
        {
            id: 3,
            question: "Metode pembelajaran seperti apa yang digunakan?",
            answer: "Kami menggunakan metode: Pembelajaran interaktif, Praktik langsung (hands-on), Studi kasus dan project, Pendampingan oleh mentor Sehingga peserta tidak hanya paham teori, tapi juga siap praktik."
        },
        {
            id: 4,
            question: "Apakah ada konsultasi sebelum memilih kursus?",
            answer: "Ada. Kami menyediakan konsultasi gratis untuk membantu peserta memilih program yang sesuai dengan tujuan dan level kemampuan."
        },
        {
            id: 5,
            question: "Bagaimana cara mendaftar di Kodein Edu Center?",
            answer: "Pendaftaran dapat dilakukan dengan: Menghubungi admin Kodein Edu Center, Melalui website atau media sosial resmi, Datang langsung ke tempat (untuk kelas offline)"
        }
    ];
    return(
        <div
        className="Kelima bg-gradient-to-br from-[#E3EEFF] to-[#FFD79E] text-slate-50 min-h-screen m-7 rounded-3xl 
             flex flex-row p-12 gap-16 
             shadow-xl overflow-hidden justify-center"
      >
        <div className="gap-7.5 flex flex-col m-20 p-6 text-white justify-center">
          <h1 className="text-[66px] font-bold">
            Pertanyaan yang sering muncul
          </h1>
          <p className="text-[20px]">
            Lorem ipsum dolor sit amet, consectetur adipiscing elit.
          </p>
        </div>

        <div className="card FAQ flex flex-col gap-6 m-20 p-6 justify-center">
          <div className="text-black text-[20px] flex flex-col gap-5">
            {data.map((d) => {
                return <Questions key={d.id} data={d} onClick={() =>showAnswer(index)} isOpen={ShowSelectedQ === index}/>
            })}
          </div>
        </div>
      </div>
    )
}