

const Questions = ({ data, onClick, isOpen }) => {
    return (
        <div className="bg-white px-4 overflow-hidden">
            <div onClick={onClick} className="flex justify-between gap-8 items-start cursor-pointer py-4">
                <h1>{data.question}</h1>
                <span>+</span>
            </div>
            <p className={`text-lg opacity-75 ${isOpen ? "max-h-96" : "max-h-0" }`}>{data.answer}</p>
        </div>
    )
};

export default Questions;